CREATE TABLE procurement_positions (
    position_id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    salary_scale TEXT,
    establishment INTEGER DEFAULT 1,
    reports_to TEXT,  -- This will store the standard_id of the supervisor
