    PRIMARY KEY (employee_id, effective_from)
);
CREATE TABLE allowance_types (
    allowance_code TEXT PRIMARY KEY,
    allowance_name TEXT NOT NULL,
    calc_method TEXT NOT NULL,
    default_value REAL NOT NULL,
    taxable INTEGER NOT NULL DEFAULT 1,
    pensionable INTEGER NOT NULL DEFAULT 0,
    active INTEGER NOT NULL DEFAULT 1,
    source_doc TEXT
, show_on_payslip INTEGER NOT NULL DEFAULT 1);
CREATE TABLE employee_allowances (
    employee_id TEXT NOT NULL,
    allowance_code TEXT NOT NULL,
    calc_method TEXT NOT NULL,
    value REAL NOT NULL,
    effective_from DATE NOT NULL,
    effective_to DATE,
    is_active INTEGER NOT NULL DEFAULT 1,
    PRIMARY KEY (employee_id, allowance_code, effective_from),
    FOREIGN KEY (allowance_code) REFERENCES allowance_types(allowance_code)
);
CREATE TABLE payroll_periods (
    period_id INTEGER PRIMARY KEY AUTOINCREMENT,
    period_code TEXT NOT NULL UNIQUE,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    pay_date DATE NOT NULL,
    status TEXT NOT NULL DEFAULT 'OPEN'
);
CREATE TABLE payroll_runs (
    run_id INTEGER PRIMARY KEY AUTOINCREMENT,
    period_id INTEGER NOT NULL,
    run_code TEXT NOT NULL UNIQUE,
    run_status TEXT NOT NULL DEFAULT 'DRAFT',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMP,
    total_employees INTEGER DEFAULT 0,
    total_basic REAL DEFAULT 0,
    total_allowances REAL DEFAULT 0,
    total_gross REAL DEFAULT 0,
    total_deductions REAL DEFAULT 0,
    total_net REAL DEFAULT 0,
    notes TEXT,
    FOREIGN KEY (period_id) REFERENCES payroll_periods(period_id)
);
CREATE TABLE payroll_run_items (
    run_item_id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id INTEGER NOT NULL,
    employee_id TEXT NOT NULL,
    employee_name TEXT,
    salary_scale TEXT,
    notch_no INTEGER,
    basic_salary REAL NOT NULL,
    allowances_total REAL NOT NULL,
    gross_pay REAL NOT NULL,
    deductions_total REAL NOT NULL,
    net_pay REAL NOT NULL, taxable_pay REAL, paye_amount REAL, napsa_amount REAL, nhima_amount REAL, position_title TEXT, position_department TEXT, salary_scale_code TEXT, establishment_position_code TEXT, authorized_establishment INTEGER, establishment_department TEXT, council_type_id INTEGER, establishment_match_method TEXT, nhis_amount REAL,
    FOREIGN KEY (run_id) REFERENCES payroll_runs(run_id)
);
CREATE TABLE payroll_run_item_allowances (
    item_allowance_id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_item_id INTEGER NOT NULL,
    allowance_code TEXT NOT NULL,
    allowance_name TEXT NOT NULL,
    calc_method TEXT NOT NULL,
    calc_value REAL NOT NULL,
    amount REAL NOT NULL, visible_on_payslip INTEGER NOT NULL DEFAULT 1,
    FOREIGN KEY (run_item_id) REFERENCES payroll_run_items(run_item_id)
);
CREATE TABLE payroll_statutory_rates (
    rate_code TEXT PRIMARY KEY,
    rate_name TEXT NOT NULL,
    rate_value REAL NOT NULL,
    cap_amount REAL,
    effective_from DATE NOT NULL,
    active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE payroll_run_item_obligations (
            item_obligation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            run_item_id INTEGER NOT NULL,
            employee_id TEXT NOT NULL,
            scheme_code TEXT NOT NULL,
            obligation_type TEXT NOT NULL,
            employee_amount REAL NOT NULL DEFAULT 0,
            employer_amount REAL NOT NULL DEFAULT 0,
            total_amount REAL NOT NULL DEFAULT 0,
            due_date DATE,
            payment_status TEXT NOT NULL DEFAULT 'PENDING',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (run_item_id) REFERENCES payroll_run_items(run_item_id)
        );
CREATE TABLE local_authorities (
    authority_id TEXT PRIMARY KEY,
    authority_code TEXT UNIQUE NOT NULL,
    authority_name TEXT NOT NULL,

    payroll_cycle TEXT DEFAULT 'MONTHLY',
    standard_pay_day INTEGER,
    pay_day_frequency TEXT,

    allows_split_payment INTEGER DEFAULT 0,
    grace_period_days INTEGER DEFAULT 0,
    max_pay_delay_days INTEGER DEFAULT 5,

    annual_payroll_budget REAL,
    current_cash_position REAL,
    last_payroll_date TEXT,
    next_payroll_date TEXT,

    payroll_bank_account TEXT,
    payroll_bank_branch TEXT,

    payroll_contact_name TEXT,
    payroll_contact_email TEXT,
    payroll_contact_phone TEXT,

    created_at TEXT DEFAULT CURRENT_TIMESTAMP
, is_active INTEGER DEFAULT 1);
CREATE TABLE payroll_schedules (
    schedule_id TEXT PRIMARY KEY,
    authority_id TEXT REFERENCES local_authorities(authority_id),
    period_year INTEGER NOT NULL,
    period_month INTEGER NOT NULL,

    payroll_cutoff_date TEXT,
    processing_start_date TEXT,
    processing_end_date TEXT,
    payslip_generation_date TEXT,
    scheduled_payment_date TEXT,

    actual_payslip_date TEXT,
    actual_payment_date TEXT,

    status TEXT DEFAULT 'SCHEDULED',
    delay_reason TEXT,

    UNIQUE(authority_id, period_year, period_month)
);
CREATE TABLE payment_batches (
    batch_id TEXT PRIMARY KEY,
    authority_id TEXT REFERENCES local_authorities(authority_id),
    schedule_id TEXT REFERENCES payroll_schedules(schedule_id),

    batch_reference TEXT UNIQUE NOT NULL,
    batch_date TEXT NOT NULL,
    total_amount REAL NOT NULL,
    employee_count INTEGER NOT NULL,

    bank_file_generated_at TEXT,
    bank_file_sent_at TEXT,
    bank_confirmation_received INTEGER DEFAULT 0,
    bank_confirmation_date TEXT,
    bank_rejection_reason TEXT,

    status TEXT DEFAULT 'CREATED'
);
CREATE TABLE payroll_integrity_log (
    log_id TEXT PRIMARY KEY,
    payroll_id TEXT,
    event_type TEXT,
    message TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE payroll_run (
            payroll_id TEXT PRIMARY KEY,
            schedule_id TEXT REFERENCES payroll_schedules(schedule_id),
            authority_id TEXT REFERENCES local_authorities(authority_id),
            employee_id TEXT,
            payslip_number TEXT UNIQUE NOT NULL,
            document_verification_code TEXT UNIQUE NOT NULL,
            payslip_available_date TEXT,
            payslip_viewed_date TEXT,
            payslip_delivery_method TEXT,
            payment_due_date TEXT,
            payment_actual_date TEXT,
            payment_status TEXT DEFAULT 'PENDING',
            payment_reference TEXT,
            basic_salary REAL,
            total_allowances REAL,
            total_deductions REAL,
            net_pay REAL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(schedule_id, employee_id)
        );
CREATE TABLE payslip_access_log (
        access_id TEXT PRIMARY KEY,
        payroll_id TEXT REFERENCES payroll_run(payroll_id),
        employee_id TEXT,
        access_type TEXT,
        access_timestamp TEXT DEFAULT CURRENT_TIMESTAMP,
        access_ip TEXT,
        access_device TEXT,
        delivery_confirmation INTEGER DEFAULT 0,
        delivery_confirmation_time TEXT
    );
CREATE TABLE payment_delay_approvals (
    delay_id TEXT PRIMARY KEY,
    authority_id TEXT REFERENCES local_authorities(authority_id),
    schedule_id TEXT REFERENCES payroll_schedules(schedule_id),
    delay_days INTEGER NOT NULL,
    reason TEXT NOT NULL,
    approved_by TEXT,
    approval_date TEXT,
    payslips_issued_on_time INTEGER DEFAULT 0,
    notification_sent_to_employees INTEGER DEFAULT 0,
    notification_date TEXT
);
CREATE TABLE la_payroll_config (
    config_id                   TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
    authority_id                TEXT REFERENCES local_authorities(authority_id),
    payslip_submission_deadline INTEGER NOT NULL DEFAULT 5,  -- day of following month
    payroll_data_deadline       INTEGER NOT NULL DEFAULT 7,
    compliance_officer_name     TEXT,
    compliance_officer_email    TEXT,
    compliance_officer_phone    TEXT,
    created_at                  TEXT DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(authority_id)
);
CREATE TABLE la_payroll_submissions (
    submission_id           TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
    authority_id            TEXT REFERENCES local_authorities(authority_id),
    period_year             INTEGER NOT NULL,
    period_month            INTEGER NOT NULL,
    la_payroll_date         TEXT,   -- ISO date; when the LA paid staff
    submission_date         TEXT DEFAULT CURRENT_TIMESTAMP,
