CREATE TABLE overtime_requests (
    overtime_id INTEGER PRIMARY KEY AUTOINCREMENT,
    
    -- Employee information
    employee_id TEXT NOT NULL,
    employee_name TEXT,
    salary_scale TEXT,
    division TEXT,  -- Division II, III, IV
    
    -- Overtime details
    overtime_date TEXT NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    hours_worked REAL,
    overtime_type TEXT DEFAULT 'normal',  -- normal, sunday, public_holiday
    
    -- Rate calculation
    hourly_rate REAL,
    rate_multiplier REAL,
    amount_earned REAL,
    
    -- REASON for working outside normal hours (Section requirement)
    reason TEXT NOT NULL,
    
    -- ============================================================
    -- STAGE 1: REQUEST INITIATION
    -- ============================================================
    requested_by_employee_id TEXT,  -- Who submitted (can be self or supervisor/HOD)
    requested_by_name TEXT,
    requested_by_role TEXT,  -- 'employee', 'supervisor', 'hod'
    is_self_request INTEGER DEFAULT 1,  -- 1 = self, 0 = on behalf
    requested_on_behalf_of_note TEXT,  -- If supervisor/HOD requested, reason why
    request_initiated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    
    -- ============================================================
    -- STAGE 2: SUPERVISOR APPROVAL
    -- ============================================================
    supervisor_approved TEXT DEFAULT 'pending',  -- pending, approved, rejected
    supervisor_approved_by TEXT,
    supervisor_approved_by_name TEXT,
    supervisor_approved_at TEXT,
    supervisor_notes TEXT,
    
    -- ============================================================
    -- STAGE 3: HEAD OF DEPARTMENT APPROVAL
    -- ============================================================
    hod_approved TEXT DEFAULT 'pending',  -- pending, approved, rejected
    hod_approved_by TEXT,
    hod_approved_by_name TEXT,
    hod_approved_at TEXT,
    hod_notes TEXT,
    
    -- ============================================================
    -- STAGE 4: PRINCIPAL OFFICER APPROVAL (Town Clerk/Council Secretary)
    -- ============================================================
    principal_officer_approved TEXT DEFAULT 'pending',  -- pending, approved, rejected
    principal_officer_approved_by TEXT,
    principal_officer_approved_by_name TEXT,
    principal_officer_approved_at TEXT,
    principal_officer_notes TEXT,
    
    -- ============================================================
    -- STAGE 5: AUDIT AUTHORIZATION (NEW - Required for payment)
    -- ============================================================
    audit_authorized TEXT DEFAULT 'pending',  -- pending, authorized, rejected, queried
    audit_authorized_by TEXT,
    audit_authorized_by_name TEXT,
    audit_authorized_at TEXT,
    audit_notes TEXT,
    audit_reference_number TEXT,  -- Unique reference from audit
    audit_query_response TEXT,    -- If audit queries, response from finance/HR
    
    -- ============================================================
    -- STAGE 6: PAYROLL INTEGRATION
    -- ============================================================
    payroll_integrated INTEGER DEFAULT 0,  -- 0 = not integrated, 1 = integrated
    payroll_run_id INTEGER,
    payroll_month TEXT,  -- YYYY-MM
    payroll_processed_at TEXT,
    payment_status TEXT DEFAULT 'pending',  -- pending, processing, paid, failed
    payment_reference TEXT,  -- Reference from payroll system
    
    -- ============================================================
    -- REJECTION & CANCELLATION
    -- ============================================================
    rejection_stage TEXT,  -- Which stage rejected (supervisor/hod/principal_officer/audit)
    rejection_reason TEXT,
    rejected_by TEXT,
    rejected_at TEXT,
    cancelled INTEGER DEFAULT 0,
    cancelled_by TEXT,
    cancelled_at TEXT,
    cancellation_reason TEXT,
    
    -- ============================================================
    -- OVERALL STATUS (Computed from above stages)
    -- ============================================================
    status TEXT DEFAULT 'draft',  -- draft, pending_supervisor, pending_hod, pending_principal_officer, pending_audit, approved, rejected, cancelled, paid
    
    -- Timestamps
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
, notch_no INTEGER, monthly_salary REAL);
