CREATE INDEX idx_payroll_assignment_exception_active ON payroll_assignment_exception(employee_id, is_active, effective_from DESC);
CREATE INDEX idx_payroll_establishment_position_match ON payroll_establishment_position(normalized_title, salary_scale_code, department_code);
CREATE INDEX idx_payroll_establishment_position_dept ON payroll_establishment_position(department_code, position_title);
CREATE VIEW vw_payroll_run_items_enriched AS
        WITH active_exception AS (
            SELECT pa1.*
            FROM payroll_assignment_exception pa1
            WHERE pa1.is_active = 1
              AND NOT EXISTS (
                  SELECT 1
                  FROM payroll_assignment_exception pa2
                  WHERE pa2.employee_id = pa1.employee_id
                    AND pa2.is_active = 1
                    AND pa2.effective_from > pa1.effective_from
              )
        )
        SELECT
            pri.run_item_id,
            pri.run_id,
            pri.employee_id,
            pri.employee_name,
            COALESCE(ae.effective_position_title, pri.position_title, e.position) AS position_title,
            COALESCE(ae.effective_department_name, pri.position_department, e.department, pep.department_name) AS department_name,
            COALESCE(ae.effective_salary_scale_code, pri.salary_scale_code, REPLACE(REPLACE(UPPER(COALESCE(pri.salary_scale, '')), '/', ''), '-', '')) AS salary_scale_code,
            pri.salary_scale AS salary_scale_raw,
            pri.notch_no,
            pri.basic_salary,
            pri.allowances_total,
            pri.gross_pay,
            pri.deductions_total,
            pri.net_pay,
            pri.taxable_pay,
            pri.paye_amount,
            pri.napsa_amount,
            pri.nhima_amount,
            pri.establishment_position_code,
            pri.authorized_establishment,
            pri.establishment_match_method,
            ae.exception_type AS assignment_exception_type,
            ae.structural_status AS assignment_structural_status,
            ae.notes AS assignment_exception_notes,
            pep.source_table AS establishment_source_table,
            pep.department_code AS establishment_department_code,
            pep.department_name AS establishment_department_name,
            pep.council_type_id AS establishment_council_type_id,
            pep.position_title AS establishment_position_title
        FROM payroll_run_items pri
        LEFT JOIN employees e
            ON CAST(e.employee_id AS TEXT) = CAST(pri.employee_id AS TEXT)
        LEFT JOIN active_exception ae
            ON ae.employee_id = CAST(pri.employee_id AS TEXT)
        LEFT JOIN payroll_establishment_position pep
            ON pep.position_code = pri.establishment_position_code;
CREATE VIEW vw_payroll_employee_effective_assignment AS
        WITH active_exception AS (
            SELECT pa1.*
            FROM payroll_assignment_exception pa1
            WHERE pa1.is_active = 1
              AND NOT EXISTS (
                  SELECT 1
                  FROM payroll_assignment_exception pa2
                  WHERE pa2.employee_id = pa1.employee_id
                    AND pa2.is_active = 1
                    AND pa2.effective_from > pa1.effective_from
              )
        )
        SELECT
            CAST(e.employee_id AS TEXT) AS employee_id,
            e.name AS employee_name,
            e.position AS recorded_position_title,
            e.department AS recorded_department,
            e.salary_scale_code AS recorded_salary_scale_code,
            e.establishment_position_code,
            e.establishment_match_method,
            pep.position_title AS structural_position_title,
            pep.department_name AS structural_department_name,
            pep.salary_scale_code AS structural_salary_scale_code,
            ae.exception_type,
            ae.structural_status,
            ae.notes AS exception_notes,
            COALESCE(ae.effective_position_title, pep.position_title, e.position) AS effective_position_title,
            COALESCE(ae.effective_department_name, pep.department_name, e.establishment_department, e.department) AS effective_department_name,
            COALESCE(ae.effective_salary_scale_code, pep.salary_scale_code, e.salary_scale_code) AS effective_salary_scale_code,
            COALESCE(ae.approval_reference, e.establishment_match_method) AS handling_reference
        FROM employees e
        LEFT JOIN payroll_establishment_position pep
            ON pep.position_code = e.establishment_position_code
        LEFT JOIN active_exception ae
            ON ae.employee_id = CAST(e.employee_id AS TEXT);
CREATE VIEW vw_payroll_position_establishment_summary AS
        WITH employee_fill AS (
            SELECT
                establishment_position_code,
                COUNT(*) AS employee_count
            FROM employees
            WHERE establishment_position_code IS NOT NULL
            GROUP BY establishment_position_code
        ),
        payroll_fill AS (
            SELECT
                establishment_position_code,
                COUNT(*) AS payroll_count
            FROM payroll_run_items
            WHERE establishment_position_code IS NOT NULL
            GROUP BY establishment_position_code
        )
        SELECT
            pep.source_table,
            pep.department_code,
            pep.department_name,
            pep.council_type_id,
            pep.position_code,
            pep.position_title,
            pep.salary_scale_code,
            pep.authorized_establishment,
            COALESCE(ef.employee_count, 0) AS current_employees,
            COALESCE(pf.payroll_count, 0) AS payroll_rows,
            pep.authorized_establishment - COALESCE(ef.employee_count, 0) AS vacancies,
            COALESCE(pf.payroll_count, 0) - pep.authorized_establishment AS payroll_variance,
            CASE
                WHEN COALESCE(ef.employee_count, 0) = 0 THEN 'VACANT'
                WHEN COALESCE(ef.employee_count, 0) < pep.authorized_establishment THEN 'UNDER STAFFED'
                WHEN COALESCE(ef.employee_count, 0) = pep.authorized_establishment THEN 'FULLY STAFFED'
                ELSE 'OVER STAFFED'
            END AS staffing_status
        FROM payroll_establishment_position pep
        LEFT JOIN employee_fill ef
            ON ef.establishment_position_code = pep.position_code
        LEFT JOIN payroll_fill pf
            ON pf.establishment_position_code = pep.position_code;
CREATE VIEW vw_payroll_department_establishment_summary AS
        SELECT
            department_code,
            department_name,
            COUNT(*) AS establishment_positions,
            SUM(authorized_establishment) AS authorized_establishment,
            SUM(current_employees) AS current_employees,
            SUM(payroll_rows) AS payroll_rows,
            SUM(vacancies) AS vacancies,
            SUM(payroll_variance) AS payroll_variance
        FROM vw_payroll_position_establishment_summary
        GROUP BY department_code, department_name
        ORDER BY department_name;
CREATE VIEW vw_payroll_unmatched_staff AS
        SELECT
            'EMPLOYEE' AS source_type,
            CAST(employee_id AS TEXT) AS source_employee_id,
            name AS employee_name,
            department,
            position AS position_title,
            salary_scale,
            salary_scale_code
        FROM employees
        WHERE establishment_position_code IS NULL
        UNION ALL
        SELECT
            'PAYROLL' AS source_type,
            CAST(employee_id AS TEXT) AS source_employee_id,
            employee_name,
            position_department AS department,
            position_title,
            salary_scale,
            salary_scale_code
        FROM payroll_run_items
        WHERE establishment_position_code IS NULL;
CREATE VIEW vw_payroll_synthetic_establishment_cleanup AS
        WITH employee_rollup AS (
            SELECT
                establishment_position_code,
                GROUP_CONCAT(name, '; ') AS employee_names,
                GROUP_CONCAT(CAST(employee_id AS TEXT), '; ') AS employee_ids,
                COUNT(*) AS employee_count
            FROM employees
            WHERE establishment_position_code IS NOT NULL
            GROUP BY establishment_position_code
        )
        SELECT
            pep.position_code,
            pep.position_title,
            pep.department_name,
            pep.salary_scale_code,
            pep.authorized_establishment,
            pep.council_type_id,
            er.employee_count,
            er.employee_ids,
            er.employee_names,
            CASE
                WHEN pep.department_name IN ('Unassigned', '60', '98') THEN 'Review department classification and create official post'
                ELSE 'Create official org-structure post and replace synthetic mapping'
            END AS recommended_action,
            pep.source_table
        FROM payroll_establishment_position pep
        LEFT JOIN employee_rollup er
            ON er.establishment_position_code = pep.position_code
        WHERE pep.source_table IN ('AUTO_UNMAPPED_EMPLOYEE', 'AUTO_UNMAPPED_PAYROLL')
        ORDER BY pep.department_name, pep.position_title, pep.position_code;
CREATE VIEW vw_payroll_forced_official_matches AS
        WITH active_exception AS (
            SELECT pa1.*
            FROM payroll_assignment_exception pa1
            WHERE pa1.is_active = 1
              AND NOT EXISTS (
                  SELECT 1
                  FROM payroll_assignment_exception pa2
                  WHERE pa2.employee_id = pa1.employee_id
                    AND pa2.is_active = 1
                    AND pa2.effective_from > pa1.effective_from
              )
        )
        SELECT
            'EMPLOYEE' AS record_source,
            CAST(e.employee_id AS TEXT) AS record_id,
            e.name AS employee_name,
            e.position AS original_position_title,
            CASE
                WHEN lower(trim(COALESCE(e.position, ''))) = 'general worker' THEN 'Engineering'
                ELSE e.department
            END AS original_department,
            e.salary_scale_code AS original_salary_scale_code,
            e.establishment_match_method,
            pep.position_code AS matched_position_code,
            pep.position_title AS matched_position_title,
            pep.department_name AS matched_department_name,
            pep.salary_scale_code AS matched_salary_scale_code,
            pep.council_type_id,
            pep.source_table AS matched_source_table
        FROM employees e
        JOIN payroll_establishment_position pep
            ON pep.position_code = e.establishment_position_code
        LEFT JOIN active_exception ae
            ON ae.employee_id = CAST(e.employee_id AS TEXT)
        WHERE e.establishment_match_method = 'forced_official_fallback'
            AND pep.source_table NOT LIKE 'AUTO_%'
            AND ae.employee_id IS NULL
            AND upper(CAST(e.employee_id AS TEXT)) NOT LIKE '%VACANT%'
            AND upper(COALESCE(e.name, '')) NOT LIKE 'VACANT%'

        UNION ALL

        SELECT
            'PAYROLL' AS record_source,
            CAST(pri.run_item_id AS TEXT) AS record_id,
            pri.employee_name,
            pri.position_title AS original_position_title,
            CASE
                WHEN lower(trim(COALESCE(pri.position_title, ''))) = 'general worker' THEN 'Engineering'
                ELSE pri.position_department
            END AS original_department,
            pri.salary_scale_code AS original_salary_scale_code,
            pri.establishment_match_method,
            pep.position_code AS matched_position_code,
            pep.position_title AS matched_position_title,
            pep.department_name AS matched_department_name,
            pep.salary_scale_code AS matched_salary_scale_code,
            pep.council_type_id,
            pep.source_table AS matched_source_table
        FROM payroll_run_items pri
        JOIN payroll_establishment_position pep
            ON pep.position_code = pri.establishment_position_code
        LEFT JOIN active_exception ae
            ON ae.employee_id = CAST(pri.employee_id AS TEXT)
        WHERE pri.establishment_match_method = 'forced_official_fallback'
            AND pep.source_table NOT LIKE 'AUTO_%'
            AND ae.employee_id IS NULL
            AND upper(CAST(pri.employee_id AS TEXT)) NOT LIKE '%VACANT%'
            AND upper(COALESCE(pri.employee_name, '')) NOT LIKE 'VACANT%'
        ORDER BY record_source, employee_name, original_position_title;
CREATE INDEX idx_overtime_employee ON overtime_requests(employee_id);
CREATE INDEX idx_overtime_status ON overtime_requests(status);
CREATE INDEX idx_overtime_date ON overtime_requests(overtime_date);
CREATE INDEX idx_overtime_audit ON overtime_requests(audit_authorized, audit_authorized_at);
CREATE INDEX idx_overtime_payroll ON overtime_requests(payroll_integrated, payroll_month);
CREATE INDEX idx_overtime_requested_by ON overtime_requests(requested_by_employee_id);
CREATE INDEX idx_overtime_principal_approval ON overtime_requests(principal_officer_approved, principal_officer_approved_at);
CREATE TRIGGER update_overtime_status AFTER UPDATE ON overtime_requests
BEGIN
    UPDATE overtime_requests 
    SET status = CASE 
        -- Rejection at any stage
        WHEN NEW.audit_authorized = 'rejected' THEN 'rejected'
        WHEN NEW.principal_officer_approved = 'rejected' THEN 'rejected'
        WHEN NEW.hod_approved = 'rejected' THEN 'rejected'
        WHEN NEW.supervisor_approved = 'rejected' THEN 'rejected'
        
        -- Cancelled
        WHEN NEW.cancelled = 1 THEN 'cancelled'
        
        -- Fully approved and audit authorized (ready for payment)
        WHEN NEW.supervisor_approved = 'approved' 
             AND NEW.hod_approved = 'approved' 
             AND NEW.principal_officer_approved = 'approved'
             AND NEW.audit_authorized = 'authorized' 
             AND NEW.payroll_integrated = 0 THEN 'approved'
        
        -- Audit stage
        WHEN NEW.supervisor_approved = 'approved' 
             AND NEW.hod_approved = 'approved' 
             AND NEW.principal_officer_approved = 'approved'
             AND NEW.audit_authorized = 'pending' THEN 'pending_audit'
        
        -- Principal Officer stage
        WHEN NEW.supervisor_approved = 'approved' 
             AND NEW.hod_approved = 'approved' 
             AND NEW.principal_officer_approved = 'pending' THEN 'pending_principal_officer'
        
        -- HOD stage
        WHEN NEW.supervisor_approved = 'approved' 
             AND NEW.hod_approved = 'pending' THEN 'pending_hod'
        
        -- Supervisor stage
        WHEN NEW.supervisor_approved = 'pending' THEN 'pending_supervisor'
        
        -- Paid
        WHEN NEW.payroll_integrated = 1 THEN 'paid'
        
        ELSE status
    END,
    updated_at = CURRENT_TIMESTAMP
    WHERE overtime_id = NEW.overtime_id;
END
;
CREATE TRIGGER onboarding_automation
AFTER INSERT ON employees
FOR EACH ROW
BEGIN
    -- Ensure sequence exists for this authority/year
    INSERT OR IGNORE INTO employee_sequence (authority_code, year, next_number)
    VALUES (NEW.authority_code, strftime('%Y', NEW.date_of_first_appointment), 0);

    -- Increment sequence
    UPDATE employee_sequence
    SET next_number = next_number + 1
    WHERE authority_code = NEW.authority_code
      AND year = strftime('%Y', NEW.date_of_first_appointment);

    -- Update the row with the NEW format: ZMXX-PREFIX-YYYY-000001
    UPDATE employees 
    SET employee_id = 
        COALESCE((SELECT province_code FROM province_codes WHERE province_name = NEW.province), 'ZMXX') || '-' ||
        NEW.authority_code || '-' ||
        strftime('%Y', NEW.date_of_first_appointment) || '-' ||
        printf('%06d', (
            SELECT next_number 
            FROM employee_sequence 
            WHERE authority_code = NEW.authority_code 
              AND year = strftime('%Y', NEW.date_of_first_appointment)
        ))
    WHERE rowid = NEW.rowid;

    -- Instantly populate the Salary Notch (remains as implemented previously)
    SELECT 
        e.employee_id,
        e.salary_scale_code,
        MIN(
            1 + MAX(0, 
                (strftime('%Y', '2026-01-01') - substr(e.date_substantive_appointment, 7, 4)) -
                (CASE WHEN strftime('%m-%d', '2026-01-01') < (substr(e.date_substantive_appointment, 4, 2) || '-' || substr(e.date_substantive_appointment, 1, 2)) THEN 1 ELSE 0 END)
            ),
            CASE 
                WHEN e.salary_scale_code LIKE 'LGSS%' THEN 7 
                WHEN e.salary_scale_code LIKE 'G%' THEN 5 
                ELSE 7 
            END
        ),
        '2026-01-01',
        1
    FROM employees e
    WHERE e.rowid = NEW.rowid
      AND e.date_substantive_appointment IS NOT NULL 
      AND e.salary_scale_code IS NOT NULL;
END
;
CREATE VIEW vw_station_stay_and_vacancy AS
SELECT 
    e.name,
    e.employee_id,
    e.position,
    e.department,
    e.date_reported as arrival_date,
    ls.years_stayed,
    ls.months_stayed,
    vs.status as occupancy_status,
    vs.vacant_and_funded_since
FROM employees e
LEFT JOIN length_of_stay ls ON e.employee_id = ls.employee_id
LEFT JOIN vacancy_status vs ON e.employee_id = vs.employee_id;
CREATE TRIGGER trg_employee_station_automation
AFTER INSERT ON employees
FOR EACH ROW
BEGIN
    -- Update Length of Stay
    INSERT OR REPLACE INTO length_of_stay (employee_id, date_reported, years_stayed, months_stayed)
    SELECT 
        NEW.employee_id,
        NEW.date_reported,
        (strftime('%Y', 'now') - substr(NEW.date_reported, 7, 4)) - (strftime('%m-%d', 'now') < (substr(NEW.date_reported, 4, 2) || '-' || substr(NEW.date_reported, 1, 2))),
        (strftime('%m', 'now') + 12 - substr(NEW.date_reported, 4, 2)) % 12
    WHERE NEW.date_reported IS NOT NULL;

    -- Update Vacancy Status to 'Filled'
    INSERT OR REPLACE INTO vacancy_status (position_code, department_name, status, filled_on, employee_id)
    VALUES (NEW.establishment_position_code, NEW.department, 'Filled', NEW.date_reported, NEW.employee_id);
END
;
CREATE TRIGGER trg_employee_vacancy_on_attrition
AFTER UPDATE OF is_active ON employees
FOR EACH ROW
WHEN NEW.is_active = 0
BEGIN
    -- Mark the position as vacant
    UPDATE vacancy_status
    SET status = 'Vacant',
        employee_id = NULL,
        vacant_and_funded_since = date('now')
    WHERE employee_id = OLD.employee_id;
    
    -- Remove from length_of_stay
    DELETE FROM length_of_stay WHERE employee_id = OLD.employee_id;
END
;
CREATE VIEW live_length_of_stay AS
SELECT 
    employee_id,
    name,
    date_reported as arrival_date,
    (strftime('%Y', 'now') - substr(date_reported, 7, 4)) - (strftime('%m-%d', 'now') < (substr(date_reported, 4, 2) || '-' || substr(date_reported, 1, 2))) as years,
    (strftime('%m', 'now') + 12 - substr(date_reported, 4, 2)) % 12 as months
FROM employees
WHERE date_reported IS NOT NULL AND date_reported != '';
CREATE VIEW vw_station_and_vacancy_summary AS
SELECT 
    e.name as employee_name,
    e.employee_id,
    e.position,
    e.department,
    v.status as vacancy_status,
    e.date_reported as arrival_date,
    ls.years_stayed,
    ls.months_stayed,
    v.vacant_and_funded_since as date_fell_vacant
FROM employees e
LEFT JOIN vacancy_status v ON e.employee_id = v.employee_id
LEFT JOIN length_of_stay ls ON e.employee_id = ls.employee_id;
COMMIT;
